1	#!/usr/bin/env node
2	// decider.js — the ONE shared fleet-wide "needs direction" decision daemon
3	// (research/IDLE_TRIGGER_SPEC.md §1.6/§3b, Direction Episodes Phase 3).
4	//
5	// Never a payload: no LLM code runs inside any bot process — this is a standalone daemon,
6	// same pattern as graybridge.js. Start: setsid nohup node decider.js >> logs/decider.log 2>&1 &
7	// Stop: kill the pid in pids/decider.pid (or just SIGTERM/SIGINT it — the pidfile is cleaned
8	// up on exit either way).
9	//
10	// Flow per POLL_MS cycle, for every bot discovered via pids/*.port (+ pids/*.meta for owner
11	// and, since #95's soak-hygiene fix, DECIDER_EXCLUDE=1 spawn-time exclusion -- a throwaway
12	// verification bot spawned alongside a formal soak/race is structurally invisible to this
13	// daemon's polling/budget/LLM path, never just a naming-convention hint):
14	//   1. GET /state; skip unless agenda.direction.state === 'needs_direction' (see agenda.js v22
15	//      / runner.js's own /state.agenda.direction — Phase 1 of this same spec).
16	//   2. Driver grace, CONDITIONAL not flat: an OWNED bot (meta names a driver) gets
17	//      DRIVER_GRACE_MS before the decider answers for it — the driver wins the race by
18	//      default. An unowned bot is answered immediately; no free grace for the driverless fleet.
19	//   3. Dedup (bot,eid) against decider-state.json — one decision per episode, mechanically,
20	//      and it survives a decider restart (the engine's own latches do not survive reinjection,
21	//      this must).
22	//   4. rules.json FIRST (key = why|role|lastError|barrenBucket) — a hit dispatches at zero
23	//      tokens, the codicil's whole point.
24	//   5. On a miss: rate gates (per-bot >=120s, fleet 30/hr, both persisted) -> compact context
25	//      from /state (+ the live skill registry, fetched via /eval) -> ONE Andy-via-Ollama call
26	//      -> map Andy's native !command(args) dialect onto the REAL registry (deterministic,
27	//      closed vocabulary -- see mapAndyCommand) -> dispatch. Felix's ruling (2026-09-02)
28	//      supersedes the original Anthropic-API-key plan: Andy (sweaterdog/andy-4:micro-q8_0,
29	//      served CPU-pinned via local Ollama as andy-cpu:latest) is zero-marginal-cost and was
30	//      always the intended long-term backend (memory: minecraft-llm-backend-plan). Andy is
31	//      fine-tuned on mindcraft-ce's own command dialect and ignores a bare-JSON format
32	//      constraint (smoke test: asked for JSON, replied `!searchForBlock("oak_log", 32)`), so
33	//      the prompt offers that dialect back rather than fighting the model's own distribution --
34	//      registry validation + retry-once-then-skip stays the backstop, same as the Haiku design.
35	//   6. Dispatch: POST /eval __agenda.dirDispatch(eid, {...decision, by:'decider'}) — the eid
36	//      compare-and-set (agenda.js §1.1j) makes a driver's own answer win the race for free; a
37	//      decider dispatch against a stale/already-answered eid is a harmless no-op.
38	//   7. Append decisions.jsonl — the rule-of-twice input for graduating (why,role,...) keys
39	//      into rules.json, and ultimately into ROLE_WORK defaults.
40	//
41	// Vocabulary is CLOSED: dirDispatch/setProject specs only. This can never become a second
42	// deliberative loop driving the body (the idleguard-subsumption law, agenda.js's own header).
43	// Decider down -> graceful degradation: the IDLE role-work floor keeps bots productive exactly
44	// as today; unanswered episodes just accumulate as the open-unclosed alarm (metrics.mjs),
45	// not as silence.
46	'use strict';
47	const fs = require('fs');
48	const path = require('path');
49	const http = require('http');
50	
51	const SELF_DIR = __dirname;
52	const PIDS_DIR = path.join(SELF_DIR, 'pids');
53	const LOGS_DIR = path.join(SELF_DIR, 'logs');
54	const DECISIONS_FILE = path.join(LOGS_DIR, 'decisions.jsonl');
55	const STATE_FILE = path.join(SELF_DIR, 'decider-state.json');
56	const RULES_FILE = path.join(SELF_DIR, 'rules.json');
57	const PID_FILE = path.join(PIDS_DIR, 'decider.pid');
58	
59	const POLL_MS = 20000;
60	const DRIVER_GRACE_MS = 60000;
61	const PER_BOT_MIN_GAP_MS = 120000;
62	const FLEET_CAP_PER_HOUR = 30;             // CPU contention is the new budget, not dollars -- cap stays (Felix's ruling)
63	// #95 soak-hygiene round 2 (2026-09-02, argued in FEEDBACK.md before building): the shared
64	// fleet cap above means a CONCURRENT bot's own LLM calls (a live race, say) compete with a
65	// formal soak's bot for the same 30/hr budget -- if the race consumes it, the soak bot's own
66	// calls can get skipped_cap'd, directly inflating its measured direction-latency for a reason
67	// that has nothing to do with the engine under test. DECIDER_EXCLUDE (spawn.sh's 4th meta
68	// field, see discoverBots() below) solves the DIFFERENT problem of a throwaway bot that
69	// shouldn't be fleet work at all -- a real fleet bot like a race entry is supposed to have
70	// decider support, excluding it would just move the contamination the other direction.
71	// SOAK_BOT names the ONE bot under formal measurement for this decider PROCESS's lifetime
72	// (set at launch, not a standing config) -- its own calls never count against the shared cap
73	// and the shared cap never blocks it, fully symmetric; everyone else keeps sharing the
74	// ordinary cap exactly as before. Still bound by PER_BOT_MIN_GAP_MS -- this is cap isolation,
75	// not a runaway-LLM exemption.
76	const SOAK_BOT = process.env.SOAK_BOT || null;
77	const HANDLED_TTL_MS = 86400000;          // prune decider-state.json's dedup map after 24h
78	const LLM_MISS_RETRY_LIMIT = 2;           // retry-once-then-skip: 2 unusable Andy replies gives up on that episode
79	const OLLAMA_HOST = process.env.OLLAMA_HOST || '127.0.0.1';
80	const OLLAMA_PORT = parseInt(process.env.OLLAMA_PORT || '11434', 10);
81	const ANDY_MODEL = process.env.ANDY_MODEL || 'andy-cpu:latest';   // andy8-cpu:latest is the bigger sibling if micro proves too dumb
82	
83	const log = (m) => console.log(`[${new Date().toISOString()}] ${m}`);
84	
85	// ---- persisted state: survives BOTH a decider restart and a bot's payload reinjection
86	// (agenda.js's own engine-side latches do not survive the latter — see spec §2.3/§2.4) ----
87	function loadState() {
88	  try { return JSON.parse(fs.readFileSync(STATE_FILE, 'utf8')); }
89	  catch (e) { return { handled: {}, lastCallAt: {}, fleetCalls: [] }; }
90	}
91	function pruneHandled(st) {
92	  const cutoff = Date.now() - HANDLED_TTL_MS;
93	  const h = st.handled || {};
94	  for (const k of Object.keys(h)) if (h[k] < cutoff) delete h[k];
95	}
96	function saveState(st) {
97	  pruneHandled(st);
98	  try { fs.mkdirSync(SELF_DIR, { recursive: true }); } catch (e) {}
99	  try { fs.writeFileSync(STATE_FILE, JSON.stringify(st)); } catch (e) { log('state save failed: ' + e.message); }
100	}
101	let state = loadState();
102	
103	function loadRules() {
104	  try { return JSON.parse(fs.readFileSync(RULES_FILE, 'utf8')); }
105	  catch (e) { return {}; }
106	}
107	
108	// ---- bot discovery: pids/*.port (control port, written by spawn.sh) + pids/*.meta
109	// (owner|server|purpose|decider_exclude, the fleet-awareness convention) ----
110	function discoverBots() {
111	  let files;
112	  try { files = fs.readdirSync(PIDS_DIR); } catch (e) { return []; }
113	  const bots = [];
114	  for (const f of files) {
115	    const m = /^(.+)\.port$/.exec(f);
116	    if (!m) continue;
117	    const name = m[1];
118	    let port;
119	    try { port = parseInt(fs.readFileSync(path.join(PIDS_DIR, f), 'utf8').trim(), 10); } catch (e) { continue; }
120	    if (!port) continue;
121	    let owner = null;
122	    // #95 soak-hygiene fix (2026-09-02): a throwaway/verification bot spawned alongside a
123	    // formal soak or race used to draw from the SAME shared fleet-wide LLM budget/rate gates
124	    // as the bot actually being measured, silently -- soak #2 was contaminated exactly this
125	    // way (SchlonzSchorsch, spawned mid-window for an unrelated fix's regression check).
126	    // DECIDER_EXCLUDE=1 at spawn time (spawn.sh's 4th meta field) makes a bot structurally
127	    // invisible to this daemon -- not a "(throwaway)" note in freeform PURPOSE text, which
128	    // existed before and enforced nothing. Excluded bots still run their own engine-side
129	    // agenda ladder exactly as always; only decider.js's polling/budget/LLM path skips them.
130	    let excluded = false;
131	    try {
132	      const meta = fs.readFileSync(path.join(PIDS_DIR, name + '.meta'), 'utf8').trim();
133	      const fields = meta.split('|');
134	      // spawn.sh writes the literal string "unowned" (not an empty field) when no OWNER is
135	      // given -- treat that sentinel as no owner, or every driverless bot would wait out the
136	      // 60s driver grace this daemon's own header comment promises it never gets.
137	      const rawOwner = (fields[0] || '').trim();
138	      owner = (rawOwner && rawOwner !== 'unowned') ? rawOwner : null;
139	      excluded = Boolean((fields[3] || '').trim());
140	    } catch (e) {}
141	    if (excluded) continue;
142	    bots.push({ name, port, owner });
143	  }
144	  return bots;
145	}
146	
147	// ---- tiny local HTTP helpers (no dependency — matches this codebase's own hand-rolled
148	// style, e.g. graybridge.js's hand-rolled RCON protocol) ----
149	function httpGetJson(port, route, timeoutMs = 5000) {
150	  return new Promise((resolve, reject) => {
151	    const req = http.get({ host: '127.0.0.1', port, path: '/' + route, timeout: timeoutMs }, (res) => {
152	      let data = '';
153	      res.on('data', (c) => { data += c; });
154	      res.on('end', () => { try { resolve(JSON.parse(data)); } catch (e) { reject(e); } });
155	    });
156	    req.on('error', reject);
157	    req.on('timeout', () => { req.destroy(); reject(new Error('timeout')); });
158	  });
159	}
160	function httpPostJson(port, route, body, timeoutMs = 15000) {
161	  return new Promise((resolve, reject) => {
162	    const payload = Buffer.from(JSON.stringify(body));
163	    const req = http.request({
164	      host: '127.0.0.1', port, path: '/' + route, method: 'POST',
165	      headers: { 'Content-Type': 'application/json', 'Content-Length': payload.length },
166	      timeout: timeoutMs,
167	    }, (res) => {
168	      let data = '';
169	      res.on('data', (c) => { data += c; });
170	      res.on('end', () => { try { resolve(JSON.parse(data)); } catch (e) { reject(e); } });
171	    });
172	    req.on('error', reject);
173	    req.on('timeout', () => { req.destroy(); reject(new Error('timeout')); });
174	    req.write(payload); req.end();
175	  });
176	}
177	const evalOn = (port, code) => httpPostJson(port, 'eval', { code });
178	
179	// ---- rule key + matching (spec §3b step 4) ----
180	function barrenBucket(n) { n = n || 0; return n === 0 ? '0' : n < 3 ? '1-2' : n < 10 ? '3-9' : '10+'; }
181	function ruleKey(direction, role) {
182	  const detail = (direction && direction.detail) || {};
183	  return [direction && direction.why, role || 'none', detail.lastError || 'none', barrenBucket(detail.barren)].join('|');
184	}
185	
186	// ---- fleet-wide rate cap: persisted rolling 1h window, never engine-side-only (spec §2.3.3) ----
187	function fleetCapOk() {
188	  const cutoff = Date.now() - 3600000;
189	  state.fleetCalls = (state.fleetCalls || []).filter((t) => t > cutoff);
190	  return state.fleetCalls.length < FLEET_CAP_PER_HOUR;
191	}
192	function recordFleetCall() { state.fleetCalls = state.fleetCalls || []; state.fleetCalls.push(Date.now()); }
193	
194	// ---- context ----
195	async function buildContext(b, st) {
196	  let skills = [];
197	  try {
198	    const r = await evalOn(b.port, 'return Object.keys(globalThis.__skills.registry);');
199	    skills = (r && r.result) || [];
200	  } catch (e) { log(`${b.name}: could not fetch skill registry: ${e.message}`); }
201	  return { state: st, skills };
202	}
203	
204	// ---- Andy's native dialect -> our skill registry ----
205	// Standalone copies of the engine's own vocabulary (decider.js is never a payload, no
206	// cross-process import -- same discipline farmskills.js documents for its own copies).
207	const SPECIES_LIST = ['oak', 'spruce', 'birch', 'jungle', 'acacia', 'dark_oak', 'cherry', 'pale_oak', 'mangrove'];
208	const ORE_ALIASES_LIST = {
209	  iron_ore: ['iron_ore', 'deepslate_iron_ore'], gold_ore: ['gold_ore', 'deepslate_gold_ore'],
210	  copper_ore: ['copper_ore', 'deepslate_copper_ore'], coal_ore: ['coal_ore', 'deepslate_coal_ore'],
211	  diamond_ore: ['diamond_ore', 'deepslate_diamond_ore'], emerald_ore: ['emerald_ore', 'deepslate_emerald_ore'],
212	  lapis_ore: ['lapis_ore', 'deepslate_lapis_ore'], redstone_ore: ['redstone_ore', 'deepslate_redstone_ore'],
213	};
214	const UBIQUITOUS_LIST = ['stone', 'deepslate', 'dirt', 'netherrack', 'cobblestone', 'grass_block', 'sand', 'gravel'];
215	const PRODUCE_RESOURCES = new Set(['torch', 'cobblestone', 'coal', 'stick', 'crafting_table']);
216	
217	function normalizeBlockArg(raw) { return String(raw || '').trim().replace(/^["']|["']$/g, '').toLowerCase(); }
218	function stripLogSuffix(name) { return name.replace(/_log$/, '').replace(/_wood$/, ''); }
219	
220	// Curated, deterministic, closed. Andy-4-micro is fine-tuned on mindcraft-ce's !command(args)
221	// syntax; the prompt below offers it a SMALL menu drawn from that same syntax (not its full
222	// ~30-command vocabulary) so it answers inside its own training distribution, and this maps
223	// that answer back onto our real skill params. Anything it says outside this menu, or whose
224	// args don't resolve to something recognizable, is a MISS -- returned as null, never guessed.
225	function mapAndyCommand(cmd, argStrs) {
226	  const num = (s, dflt) => { const n = parseInt(String(s || '').trim(), 10); return Number.isFinite(n) ? n : dflt; };
227	  if (cmd === 'goToSurface') return { skill: 'ascendToSurface', args: {} };
228	  if (cmd === 'searchForBlock' || cmd === 'collectBlocks') {
229	    const block = normalizeBlockArg(argStrs[0]);
230	    const n2 = num(argStrs[1], null);
231	    const species = stripLogSuffix(block);
232	    if (SPECIES_LIST.includes(species)) {
233	      const args = { types: [species] };
234	      if (cmd === 'searchForBlock') args.maxDist = n2 || 32; else args.count = n2 || 4;
235	      return { skill: 'chopTrees', args };
236	    }
237	    const oreKey = Object.keys(ORE_ALIASES_LIST).find((k) => ORE_ALIASES_LIST[k].includes(block)) || null;
238	    if (oreKey || UBIQUITOUS_LIST.includes(block)) {
239	      const args = { target: oreKey || block };
240	      if (cmd === 'searchForBlock') args.maxDist = n2 || 32; else args.count = n2 || 4;
241	      return { skill: 'mineLane', args };
242	    }
243	    return null;
244	  }
245	  if (cmd === 'craftRecipe') {
246	    const item = normalizeBlockArg(argStrs[0]);
247	    const n2 = num(argStrs[1], 16);
248	    if (PRODUCE_RESOURCES.has(item) || /_planks$/.test(item)) return { skill: 'produce', args: { resource: item, count: n2 } };
249	    return null;
250	  }
251	  if (cmd === 'attack') {
252	    const species = normalizeBlockArg(argStrs[0]);
253	    if (species && species !== 'player') return { skill: 'huntAnimals', args: { species: [species] } };
254	    return null;
255	  }
256	  return null;
257	}
258	function parseAndyResponse(raw) {
259	  if (!raw) return null;
260	  const m = /!([A-Za-z_][A-Za-z0-9_]*)\(([^)]*)\)/.exec(raw);
261	  if (!m) return null;
262	  return { cmd: m[1], argStrs: m[2].trim() ? m[2].split(',').map((x) => x.trim()) : [] };
263	}
264	const SITUATIONS = {
265	  unproductive_idle: 'has been idle with no clear task for a while',
266	  project_stalled: 'has a project that stopped making progress',
267	  no_path: 'is stuck -- no path found to its goal',
268	  no_tool: 'lacks a tool it needs',
269	  respawned: 'just died and respawned, and has no project',   // #103
270	};
271	// A bare closed-menu instruction ("reply with exactly one of these five") did NOT reliably hold
272	// Andy-4-micro to the menu in smoke testing -- it answers from its own ~30-command fine-tuned
273	// vocabulary regardless (e.g. `!moveAway(10)`, `!goToPlayer(...)`, `!newAction(...)`, or plain
274	// chat with no `!command` at all). A one-shot example in its OWN dialect measurably improved
275	// compliance on the matching case. This is expected to stay imperfect -- misses are logged with
276	// raw text (not guessed into a dispatch) precisely so the mapping in mapAndyCommand can widen
277	// over time from what Andy actually says, per Felix's "study the dialect" instruction.
278	function buildAndyPrompt(ctx) {
279	  const s = ctx.state;
280	  const a = s.agenda || {};
281	  const d = a.direction || {};
282	  return [
283	    `You are ${s.name}, a Minecraft bot deciding your next action.`,
284	    `Stats: health: ${s.health}, hunger: ${s.food}`,
285	    'Available commands:',
286	    '!goToSurface() - dig upward to open sky',
287	    '!searchForBlock(block_name, distance) - go mine the nearest block of this type',
288	    '!collectBlocks(block_name, count) - mine several blocks of this type nearby',
289	    '!craftRecipe(item_name, count) - craft this item',
290	    '!attack(animal_name) - hunt this animal',
291	    '',
292	    'Example:',
293	    'Situation: has been idle with no clear task for a while',
294	    'Response: !searchForBlock("oak_log", 32)',
295	    '',
296	    `Situation: ${SITUATIONS[d.why] || d.why || 'needs a new task'}`,
297	    'Response:',
298	  ].join('\n');
299	}
300	
301	// Guard inherited from mindcraft-ce/andy-start.sh: refuse the LLM path if Ollama has offloaded
302	// ANDY_MODEL onto the GPU (andy-cpu must stay CPU-pinned). Not loaded yet is NOT a failure --
303	// there's nothing to check until the first call loads it; a request/parse hiccup fails open
304	// (`ok:true`) rather than blocking the whole soak on an ops-check the real /api/chat call would
305	// surface anyway.
306	function checkCpuPinned() {
307	  return new Promise((resolve) => {
308	    const req = http.get({ host: OLLAMA_HOST, port: OLLAMA_PORT, path: '/api/ps', timeout: 5000 }, (res) => {
309	      let data = '';
310	      res.on('data', (c) => { data += c; });
311	      res.on('end', () => {
312	        try {
313	          const j = JSON.parse(data);
314	          const m = (j.models || []).find((mm) => mm.name === ANDY_MODEL || mm.model === ANDY_MODEL);
315	          if (!m) return resolve({ ok: true, loaded: false });
316	          resolve({ ok: (m.size_vram || 0) === 0, loaded: true, vram: m.size_vram || 0 });
317	        } catch (e) { resolve({ ok: true, loaded: false }); }
318	      });
319	    });
320	    req.on('error', () => resolve({ ok: true, loaded: false }));
321	    req.on('timeout', () => { req.destroy(); resolve({ ok: true, loaded: false }); });
322	  });
323	}
324	async function askAndy(ctx) {
325	  const guard = await checkCpuPinned();
326	  if (!guard.ok) {
327	    log(`ABORT LLM path: ${ANDY_MODEL} size_vram=${guard.vram} (>0, on GPU) -- fix the model pin before spending another call`);
328	    return { decision: null, raw: null, aborted: 'gpu_pinned' };
329	  }
330	  const prompt = buildAndyPrompt(ctx);
331	  const body = JSON.stringify({ model: ANDY_MODEL, messages: [{ role: 'user', content: prompt }], stream: false });
332	  const raw = await new Promise((resolve) => {
333	    const req = http.request({
334	      host: OLLAMA_HOST, port: OLLAMA_PORT, path: '/api/chat', method: 'POST',
335	      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) },
336	      timeout: 30000,
337	    }, (res) => {
338	      let data = '';
339	      res.on('data', (c) => { data += c; });
340	      res.on('end', () => {
341	        try { const j = JSON.parse(data); resolve((j.message && j.message.content) || null); }
342	        catch (e) { log('andy response parse failed: ' + e.message); resolve(null); }
343	      });
344	    });
345	    req.on('error', (e) => { log('andy call failed: ' + e.message); resolve(null); });
346	    req.on('timeout', () => { req.destroy(); log('andy call timed out'); resolve(null); });
347	    req.write(body); req.end();
348	  });
349	  if (!raw) return { decision: null, raw: null };
350	  const parsed = parseAndyResponse(raw);
351	  if (!parsed) { log(`${ctx.state.name}: no !command() found in Andy's reply: ${raw.slice(0, 200)}`); return { decision: null, raw }; }
352	  const mapped = mapAndyCommand(parsed.cmd, parsed.argStrs);
353	  if (!mapped) { log(`${ctx.state.name}: Andy's '!${parsed.cmd}(...)' didn't map to a known skill -- discarding, not dispatching garbage`); return { decision: null, raw }; }
354	  return { decision: mapped, raw };
355	}
356	
357	function appendDecision(rec) {
358	  try { fs.mkdirSync(LOGS_DIR, { recursive: true }); } catch (e) {}
359	  try { fs.appendFileSync(DECISIONS_FILE, JSON.stringify(rec) + '\n'); } catch (e) { log('decisions.jsonl append failed: ' + e.message); }
360	}
361	
362	// ---- per-bot handling ----
363	async function handleBot(b, rules) {
364	  let st;
365	  try { st = await httpGetJson(b.port, 'state'); } catch (e) { return; }   // unreachable -- skip silently, next poll retries
366	  const dir = st.agenda && st.agenda.direction;
367	  if (!dir || dir.state !== 'needs_direction' || !dir.eid) return;
368	  const eid = dir.eid;
369	
370	  // step 2: conditional driver grace -- an OWNED bot's driver wins the race by default
371	  if (b.owner && (dir.forMs || 0) < DRIVER_GRACE_MS) return;
372	
373	  // step 3: dedup (bot,eid) -- one decision per episode, mechanically, across restarts
374	  state.handled = state.handled || {};
375	  const dedupKey = b.name + ':' + eid;
376	  if (state.handled[dedupKey]) return;
377	
378	  // #97 item 3: a bot that hasn't moved AND is stalling on the exact same why+lastError as
379	  // its LAST dispatch attempt is very unlikely to be helped by dispatching the identical
380	  // thing again -- test-driver's live evidence: three identical chopTrees dispatches from a
381	  // frozen position, back to back, across three separate episodes. Track the signature at
382	  // every genuinely-new-episode attempt (this runs once per eid, gated by the dedup check
383	  // above) and skip the WHOLE decision -- saving an Andy call too, not just the dispatch --
384	  // when nothing observable about the situation has changed since last time. Closes the
385	  // episode via the SAME dirClose #95 already built (closedBy:'frozen_repeat') rather than
386	  // either blindly re-dispatching an identical failing call or leaving the episode open --
387	  // the exact same reopen-backoff every other close uses gives it another shot later if the
388	  // world (position, kit, whatever) actually changes.
389	  // TWO BUGS FOUND LIVE during the deferred wiring check this fixture-zero comment promised
390	  // (2026-09-02, both on the actual restart -- exactly why that check was deferred rather
391	  // than assumed):
392	  // 1. Without an eid in the tracked signature, this fired on the SECOND POLL OF THE SAME
393	  //    STILL-RETRYING EPISODE, not just across genuinely separate episodes -- every poll
394	  //    that passes dedup (including a mid-retry re-poll of an episode decider hasn't given
395	  //    up on yet) unconditionally rewrote `lastAttempt` to the identical {pos,why,lastError},
396	  //    so the very next poll compared it against itself and always matched, short-circuiting
397	  //    the 2-attempt-then-give-up Andy retry after just ONE attempt. Fixed by tracking `eid`
398	  //    and requiring it to DIFFER -- matching within the SAME eid is decider re-polling its
399	  //    own in-progress retry, not a repeat.
400	  // 2. `prevAttempt.eid !== eid` alone is backwards on missing data: a `lastAttempt` entry
401	  //    persisted by the OLD code (no `eid` field, live in decider-state.json across this
402	  //    exact restart) has `eid: undefined`, and `undefined !== "realEid"` is true -- so a
403	  //    STALE entry with no real signal read as "confirmed different episode" and false-
404	  //    triggered against BruzzelBruno's genuinely in-progress retry the instant this
405	  //    restarted, costing it one legitimate Andy attempt (not left stuck -- dirClose +
406	  //    reopen-backoff still applied -- but a real, avoidable false positive). `&&
407	  //    prevAttempt.eid` requires an ACTUAL prior eid before ever treating "different" as
408	  //    meaningful -- missing/ambiguous data defaults to "don't skip", not "skip", matching
409	  //    this codebase's own never-guess-on-missing-data doctrine everywhere else.
410	  const FROZEN_POS_TOLERANCE = 1.5;   // blocks -- "hasn't moved" allows for settle/jitter
411	  state.lastAttempt = state.lastAttempt || {};
412	  const prevAttempt = state.lastAttempt[b.name];
413	  const curPos = st.position || null;
414	  const lastError = (dir.detail && dir.detail.lastError) || null;
415	  const frozenRepeat = Boolean(prevAttempt && prevAttempt.eid && prevAttempt.eid !== eid && curPos
416	    && Math.abs(curPos.x - prevAttempt.pos.x) < FROZEN_POS_TOLERANCE
417	    && Math.abs(curPos.y - prevAttempt.pos.y) < FROZEN_POS_TOLERANCE
418	    && Math.abs(curPos.z - prevAttempt.pos.z) < FROZEN_POS_TOLERANCE
419	    && prevAttempt.why === dir.why && prevAttempt.lastError === lastError);
420	  if (curPos) state.lastAttempt[b.name] = { pos: curPos, why: dir.why, lastError, eid };
421	  if (frozenRepeat) {
422	    state.handled[dedupKey] = Date.now();
423	    appendDecision({ t: Date.now(), bot: b.name, eid, why: dir.why, key: ruleKey(dir, st.role || null),
424	      src: 'skipped_frozen_repeat', decision: null, latency_ms: null });
425	    try { await evalOn(b.port, `return __agenda.dirClose(${JSON.stringify(eid)}, 'frozen_repeat');`); }
426	    catch (e) { /* best-effort -- worst case, episode just stays open as it always did */ }
427	    log(`${b.name}: skipping an identical dispatch from a frozen position (why=${dir.why}, lastError=${lastError}) -- closed frozen_repeat so a fresh episode can reopen if the world actually changes`);
428	    return;
429	  }
430	
431	  const role = st.role || null;
432	  const key = ruleKey(dir, role);
433	  const rule = rules[key];
434	  let decision = null, src = null, decisionLatencyMs = null, raw = null;
435	
436	  if (rule) {
437	    decision = rule; src = 'rule'; decisionLatencyMs = 0;
438	  } else {
439	    // step 5: rate gates BEFORE spending anything
440	    const lastAt = (state.lastCallAt || {})[b.name] || 0;
441	    if (Date.now() - lastAt < PER_BOT_MIN_GAP_MS) return;   // this bot's spacing hasn't elapsed; try again next poll, not a permanent skip
442	    // #95 soak-hygiene: the designated SOAK_BOT bypasses the shared fleet cap entirely, both
443	    // directions -- unrelated fleet activity (a concurrent race, say) can never delay it, and
444	    // its own calls never eat into the budget everyone else shares.
445	    if (b.name !== SOAK_BOT && !fleetCapOk()) {
446	      appendDecision({ t: Date.now(), bot: b.name, eid, why: dir.why, key, src: 'skipped_cap', decision: null, latency_ms: null });
447	      return;   // logged, never spent -- the overflow is visible, not silent
448	    }
449	    const ctx = await buildContext(b, st);
450	    const t0 = Date.now();
451	    const { decision: mapped, raw: rawOut, aborted } = await askAndy(ctx);
452	    if (aborted) return;   // guard blocked before any inference ran -- no rate/cap charge, no decisions.jsonl noise; the console warning is the ops signal
453	    state.lastCallAt = state.lastCallAt || {}; state.lastCallAt[b.name] = Date.now();
454	    if (b.name !== SOAK_BOT) recordFleetCall();
455	    const llmLatencyMs = Date.now() - t0;
456	    if (!mapped || typeof mapped.skill !== 'string' || !ctx.skills.includes(mapped.skill)) {
457	      // logged with the RAW model output regardless of outcome (#68 Phase 3 dialect-study ask) --
458	      // a rule/llm miss used to vanish into a console line only; now it's in decisions.jsonl too.
459	      state.llmMisses = state.llmMisses || {};
460	      state.llmMisses[dedupKey] = (state.llmMisses[dedupKey] || 0) + 1;
461	      appendDecision({ t: Date.now(), bot: b.name, eid, why: dir.why, key, src: 'llm', decision: null,
462	        raw: (rawOut || '').slice(0, 500), latency_ms: llmLatencyMs, dispatchOk: false, dispatchError: 'unmapped_or_unparsed' });
463	      if (state.llmMisses[dedupKey] >= LLM_MISS_RETRY_LIMIT) {
464	        state.handled[dedupKey] = Date.now();   // retry-once-then-skip: give up, the IDLE floor/driver/a future rule takes it from here
465	        // #95: a give-up used to stop here -- "handled" only in decider-state.json, the
466	        // episode itself never closed, and agenda's own single-latch (openEpisode's `if
467	        // (d.episode) return`) then silently blocked every future stall detection for as
468	        // long as the underlying condition persisted (soak #2's dead-consumer: 9+ repeat
469	        // kit_missing failures over 30+ minutes, zero further direction-episode activity of
470	        // any kind). Close it explicitly via dirClose (same eid-CAS safety as dirDispatch,
471	        // touches nothing but the episode) so agenda's existing per-`why` reopen backoff
472	        // (30s->60s->120s->300s) gets a chance to open a FRESH episode later if the stall is
473	        // still real -- giving the decider (or a driver, or a future rule) another shot
474	        // instead of permanent silence. Fire-and-forget: if this fails (bot gone, network),
475	        // the episode just stays open as it always did -- no new failure mode introduced.
476	        try {
477	          await evalOn(b.port, `return __agenda.dirClose(${JSON.stringify(eid)}, 'decider_exhausted');`);
478	        } catch (e) { /* best-effort -- worst case, unchanged from today's behavior */ }
479	        log(`${b.name}: giving up on episode ${eid} after ${LLM_MISS_RETRY_LIMIT} unusable Andy replies -- closed decider_exhausted so a fresh episode can reopen later`);
480	      } else {
481	        log(`${b.name}: no usable decision from Andy for episode ${eid} (attempt ${state.llmMisses[dedupKey]}/${LLM_MISS_RETRY_LIMIT})`);
482	      }
483	      return;
484	    }
485	    decision = mapped; src = 'llm'; decisionLatencyMs = llmLatencyMs; raw = (rawOut || '').slice(0, 500);
486	  }
487	
488	  let dispatchOk = false, dispatchError = null;
489	  try {
490	    const spec = JSON.stringify(Object.assign({}, decision, { by: 'decider' }));
491	    const r = await evalOn(b.port, `return __agenda.dirDispatch(${JSON.stringify(eid)}, ${spec});`);
492	    dispatchOk = Boolean(r && r.result && r.result.ok);
493	    if (!dispatchOk) dispatchError = r && r.result && (r.result.error || r.result.skipped);
494	  } catch (e) { dispatchError = e.message; }
495	
496	  // mark handled REGARDLESS of dispatch outcome: a validated decision that failed to dispatch
497	  // (e.g. the episode closed itself in the meantime -- a driver answered first) is still
498	  // "handled" for this eid; retrying would just re-derive the same stale-eid no-op forever.
499	  state.handled[dedupKey] = Date.now();
500	  appendDecision({ t: Date.now(), bot: b.name, eid, why: dir.why, key, src, decision, raw, latency_ms: decisionLatencyMs, dispatchOk, dispatchError });
501	  log(`${b.name}: ${src} decision for '${dir.why}' -> ${decision.skill} (dispatch ${dispatchOk ? 'ok' : 'FAILED: ' + dispatchError})`);
502	}
503	
504	async function pollOnce() {
505	  const bots = discoverBots();
506	  const rules = loadRules();
507	  for (const b of bots) {
508	    try { await handleBot(b, rules); } catch (e) { log(`${b.name}: poll error: ${e.message}`); }
509	  }
510	  saveState(state);
511	}
512	
513	// ---- pid-file guard (graybridge.js's own pattern) ----
514	try { fs.mkdirSync(PIDS_DIR, { recursive: true }); } catch (e) {}
515	try {
516	  if (fs.existsSync(PID_FILE)) {
517	    const oldPid = parseInt(fs.readFileSync(PID_FILE, 'utf8').trim(), 10);
518	    let alive = false;
519	    try { process.kill(oldPid, 0); alive = true; } catch (e) { alive = false; }
520	    if (alive) { log(`refusing to start: decider already running (pid ${oldPid})`); process.exit(1); }
521	    log(`stale pidfile (pid ${oldPid} not running) -- taking over`);
522	  }
523	  fs.writeFileSync(PID_FILE, String(process.pid));
524	} catch (e) { log('pidfile guard warning (continuing anyway): ' + e.message); }
525	const cleanupPid = () => { try { fs.unlinkSync(PID_FILE); } catch (e) {} };
526	process.on('exit', cleanupPid);
527	process.on('SIGINT', () => { cleanupPid(); process.exit(0); });
528	process.on('SIGTERM', () => { cleanupPid(); process.exit(0); });
529	
530	log(`decider.js starting -- poll every ${POLL_MS / 1000}s, driver grace ${DRIVER_GRACE_MS / 1000}s, fleet cap ${FLEET_CAP_PER_HOUR}/hr, model ${ANDY_MODEL} via ${OLLAMA_HOST}:${OLLAMA_PORT}${SOAK_BOT ? `, SOAK_BOT=${SOAK_BOT} (exempt from fleet cap, both directions)` : ''}`);
531	checkCpuPinned().then((g) => {
532	  if (g.loaded && !g.ok) log(`WARNING: ${ANDY_MODEL} is already loaded with size_vram=${g.vram} (on GPU) -- the LLM path will refuse to call until this is fixed; rule.json hits are unaffected`);
533	});
534	setInterval(() => { pollOnce().catch((e) => log('poll cycle error: ' + e.message)); }, POLL_MS);
535	pollOnce().catch((e) => log('initial poll error: ' + e.message));
536

