564	  } catch (e) { return false; }
565	};
566	
567	const torchInline = async () => {
568	  try {
569	    const t = bot.inventory.items().find((i) => i.name === 'torch');
570	    if (!t) return false;
571	    const feet = bot.entity.position.floored();
572	    const ref = bot.blockAt(feet.offset(0, -1, 0));
573	    if (!ref || ref.boundingBox !== 'block') return false;
574	    await bot.equip(t, 'hand');
575	    await bot.placeBlock(ref, new Vec3(0, 1, 0));
576	    return true;
577	  } catch (e) { return false; }
578	};
579	
580	// ---------------- #67b: base-barren detection + relocate trigger ----------------
581	// IDLE role-work can no-op: at a worked-out or protected base, chopTrees/mineLane throw
582	// not_found and safeDescend/harvestGrass return a zero-yield result. Standing there re-running
583	// the same empty scan is the "five bots frozen" bug one level up. So we GRADE each finished
584	// IDLE work run, count consecutive barren outcomes, and once the ground is proven empty walk the
585	// bot to fresh terrain (the relocateToWork skill) before letting it try its trade again.
586	const RELOCATABLE = new Set(['chopTrees', 'harvestGrass', 'mineLane', 'safeDescend']);
587	const BARREN_ERRS = new Set(['not_found', 'no_target', 'none']);   // "nothing of the kind here"
588	// #89: a project's own error code, once p.blocked (PROJECT's act(), 3 failed attempts),
589	// that means "cannot get there" rather than "nothing to find" or "missing kit/tool" — the
590	// ESCAPE rung's trigger for a bot that may have dug itself into a sealed pocket.
591	const PATH_BLOCKED = new Set(['no_path', 'unreachable', 'stuck']);
592	// worked | barren | other. 'other' (kit_missing, no_tool, busy) is NOT barren — RESTOCK/TOOL own
593	// it — so it must never trip a relocate. Unknown skills default to 'worked' so a bot making
594	// progress we cannot read is never marched off its work.
595	const idleWorkOutcome = (skill, result, error) => {
596	  if (error) return BARREN_ERRS.has(error.code) ? 'barren' : 'other';
597	  const r = result || {};
598	  const did = ({
599	    chopTrees:      () => (r.treesFelled || 0) > 0,
600	    harvestGrass:   () => (r.cut || 0) > 0,
601	    mineLane:       () => (r.dug || 0) > 0,
602	    safeDescend:    () => (r.endY != null && r.startY != null) ? r.endY < r.startY : true,
603	    spawnProof:     () => (r.placed || 0) > 0,   // #72: 0 placed = base already lit (barren base-chore)
604	    relocateToWork: () => Boolean(r.relocated),
605	  }[skill] || (() => true))();
606	  return did ? 'worked' : 'barren';
607	};
608	A._idleWorkOutcome = idleWorkOutcome;   // exposed for bench/fixtures/agenda-idlework.js
609	const RELOCATE_BACKOFF_MS = 5 * 60000;
610	const RELOCATE_WANDER_CAP = 5;          // hops without finding work before we settle and sweep
611	// Grade the IDLE work run we last started, exactly once, the tick it is found finished.
612	// S.currentTask persists after done until the next start, so the terminal result/error is on the
613	// snapshot; injected test snapshots that omit _raw simply skip, as deterministic replay wants.
614	// openEpisode/closeEpisode: the single latch. At most one open episode per bot — a second
615	// openEpisode call while one is already open, or while its per-`why` reopen backoff hasn't
616	// expired, is a no-op (backoff instead sets state:'cooldown', VISIBLE on /state — nothing is
617	// silently suppressed; see markProductive below for how reopenCount resets).
618	let _epSeq = 0;
619	const openEpisode = (why, detail, s) => {
620	  const d = A.direction;
621	  if (d.episode) return;                                         // single-latch
622	  if ((d.reopenAt[why] || 0) > s.now) { d.state = 'cooldown'; return; }  // deferred, not suppressed
623	  const eid = 'd' + Date.now().toString(36) + (++_epSeq);
624	  d.episode = { id: eid, why, openedAt: s.now, detail };
625	  d.state = 'needs_direction';
626	  d.opened++; d.byWhy[why] = (d.byWhy[why] || 0) + 1;
627	  dirEmit('open', { eid, why, project: A.project ? A.project.skill : null, detail, rung: A.owner ? A.owner.id : null, pos: s.pos || null });
628	};
629	const closeEpisode = (closedBy, skill, s) => {
630	  const d = A.direction;
631	  const ep = d.episode;
632	  if (!ep) return;
633	  const latency_ms = s.now - ep.openedAt;
634	  d.closed++;
635	  const n = d.reopenCount[ep.why] || 0;
636	  d.reopenAt[ep.why] = s.now + DIRECTION_REOPEN_MS[Math.min(n, DIRECTION_REOPEN_MS.length - 1)];
637	  d.reopenCount[ep.why] = n + 1;
638	  dirEmit('close', { eid: ep.id, why: ep.why, closedBy, latency_ms, skill: skill || null });
639	  d.episode = null;
640	  d.state = 'ok';
641	};
642	
643	// markProductive: the churn-proof productivity clock. Stamped ONLY by verified-outcome
644	// branches (never A.ownerSince — tick's NO_PROGRESS handler nulls the owner even at the
645	// floor, so ownerSince can never accumulate a window on a wedged bot). Resets the per-why
646	// reopen backoff counters (a real recovery earns a fresh, non-escalated backoff next time)
647	// and, if an episode happens to be open, closes it — a bot that fixed itself before anything
648	// answered the episode should read as self-recovered, not left open forever.
649	const markProductive = (s, src) => {
650	  A.direction.lastProductiveAt = s.now;
651	  A.direction.reopenCount = {};
652	  if (A.direction.episode) closeEpisode('self_recovered', src, s);
653	};
654	
655	// #68 (h): the central direction-episode detector. Called once per tick, immediately after
656	// the harvest block closes and BEFORE choose(s) picks a rung — so an episode opened this tick
657	// is already visible to whichever rung consults it (today: none; ESCAPE and any future
658	// consumer read A.direction/A.project directly, same as everything else in this file).
659	// Exposed as A._directionCheck for fixtures, same discipline as A._idleWorkOutcome.
660	const directionCheck = (s) => {
661	  // #103: the respawn flag lives on `bot`, not on `A` (see its own comment at module init,
662	  // above — a double-injection race can otherwise lose it). Checked first — a bot that JUST
663	  // died is provably projectless and idle, not probably, so this doesn't wait on the
664	  // composite-level edges below to eventually infer the same thing.
665	  if (bot._respawnedNeedsDirection) {
666	    bot._respawnedNeedsDirection = false;
667	    openEpisode('respawned', {}, s);
668	  }
669	  // composite level — catches EVERY current/future mutation site of p.blocked / completedOnce
670	  // / A.blocked (including a driver's own /eval writes) without a per-site call at each one.
671	  const p = A.project;
672	  const lvl = !p ? 'none'
673	    : p.blocked ? 'blocked'
674	    : (A.blocked && A.blocked.why === 'no_tool') ? 'no_tool'   // its OWN arm: projectDone() never reads A.blocked
675	    : projectDone(s) ? 'done' : 'active';
676	  const prev = A.direction.prevLvl;
677	  A.direction.prevLvl = lvl;
678	  // EDGES (project lifecycle) — fire once, on the transition into the level, never while
679	  // already in it (so a level that stays 'blocked' for an hour opens exactly one episode).
680	  if (prev === 'active' && lvl === 'done') openEpisode('project_done', { skill: p.skill }, s);
681	  if (prev !== 'blocked' && lvl === 'blocked') openEpisode('project_blocked', { skill: p.skill, lastError: p.lastError, attempts: p.attempts }, s);
682	  if (prev !== 'no_tool' && lvl === 'no_tool') openEpisode('no_tool', { cls: A.blocked.cls }, s);
683	  // LEVELS (windows on the churn-proof productivity clock). Gated on no in-flight task so a
684	  // long productive run (a 200-block haul) can never false-fire — a wedged RUNNING act is
685	  // ACT_TIMEOUT_MS/busyStuck's jurisdiction, not this detector's.
686	  const running = Boolean(s.task && s.task.running);
687	  const quiet = s.now - A.direction.lastProductiveAt;
688	  if (!p && !running && quiet > DIRECTION_IDLE_WINDOW_MS) {
689	    openEpisode('unproductive_idle', { barren: A._barren || 0, role: A.role }, s);   // E2
690	  }
691	  if (p && !projectDone(s) && !running && quiet > DIRECTION_STALL_MS) {
692	    // E3a — the kit-deadlock catcher: kit_missing/no_tool reset p.attempts on every refused
693	    // start (the repair-not-block rule), so p.blocked never latches for a project stuck
694	    // behind a gate the maintenance rungs keep failing to clear. This window catches it by
695	    // productivity, not by attempt-counting.
696	    openEpisode('project_stalled', { skill: p.skill, lastError: p.lastError, blocked: A.blocked && A.blocked.why }, s);
