}
if (A._yieldedToNav) { A._yieldedToNav = false; note('/goto2 released the body — resuming'); }
if (s.dangerState === 'calm' && A.calmSince === 0) A.calmSince = s.now;
if (s.dangerState !== 'calm') A.calmSince = 0;

