4035	S.define('restock', {
4036	  description: 'Top inventory up to the given floors from the depot chests. Idempotent: floors are targets, not deltas.',
4037	  params: {
4038	    needs: "{itemName: targetTotal}, e.g. {torch:16, bread:4, cobblestone:16}",
4039	    chests: 'optional [{x,y,z}] to try in order (default: the depot coords in protected.json)',
4040	  },
4041	  validate: (a) => (a.needs && typeof a.needs === 'object' && Object.keys(a.needs).length ? null : 'need {needs:{item:count}}'),
4042	  fn: async (ctx) => {
4043	    const { bot, args } = ctx;
4044	    const have = (n) => bot.inventory.items().filter((i) => i.name === n).reduce((a, i) => a + i.count, 0);
4045	    const shortfall = () => {
4046	      const out = {};
4047	      for (const [n, target] of Object.entries(args.needs)) {
4048	        const gap = target - have(n);
4049	        if (gap > 0) out[n] = gap;
4050	      }
4051	      return out;
4052	    };
4053	    let need = shortfall();
4054	    if (!Object.keys(need).length) return { alreadyStocked: true, got: {}, short: {} };
4055	
4056	    const cfg = readCfg();
4057	    const depot = cfg.depot || {};
4058	    const chests = Array.isArray(args.chests) && args.chests.length ? args.chests
4059	      : ['minerals', 'wood', 'food'].map((k) => depot[k]).filter(Array.isArray).map((c) => ({ x: c[0], y: c[1], z: c[2] }));
4060	    if (!chests.length) throw fatal('not_found', 'no depot chests configured', 'add a depot block to protected.json or pass chests:[{x,y,z}]');
4061	
4062	    ctx.setPhase('restocking', `Topping up: ${Object.entries(need).map(([n, c]) => c + ' ' + n).join(', ')}.`);
4063	    // A restock is a long haul by nature — the depot is at the surface and the bot calling
4064	    // this is usually deep. On the default profile that route is beyond the planner's search
4065	    // budget: the soak ledger shows a y62->surface trip returning `partial` 416 times with
4066	    // ZERO successes, inching ~17 blocks of a 76-block ascent before wedging, and it did that
4067	    // ten times in a row. HAUL is what that route needs (thinkTimeout 25s, unlimited
4068	    // searchRadius, path shortcuts) and it is the same treatment `come` already gets.
4069	    const restoreMoves = ctx.enterHaul();
4070	    try {
4071	    const got = {};
4072	    // How many chests we actually OPENED. "The depot was out" and "we never got to the
4073	    // depot" are different facts and they deserve different responses, but the result used
4074	    // to report both as an identical `short`. That mattered once it was measured: on a world
4075	    // where the depot does not exist, this whole call cost ~7 minutes of hauling toward
4076	    // coordinates it could not reach, and the agenda's 10-minute retry would have had a
4077	    // driverless bot spending most of a soak walking to a chest that was never there.
4078	    let reached = 0;
4079	    for (const c of chests) {
4080	      ctx.step();
4081	      need = shortfall();
4082	      if (!Object.keys(need).length) break;
4083	      let r = null;
4084	      try { r = await ctx.withdrawFromChest(c, need); reached++; }
4085	      catch (e) { ctx.log(`chest ${c.x},${c.y},${c.z}: ${e.message}`); continue; }
