1	// bench/fixtures/agenda-ladder.js — the agenda's ladder regression, run through the
2	// MANDATORY dry-run hook (research/AGENDA-DESIGN.md: "__agenda.step(injectedSnapshot)
3	// returns the chosen rung WITHOUT executing"). Executes nothing, moves nothing, and is safe
4	// to run against a live bot: it saves and restores every field it touches.
5	//
6	// Run:  curl -s localhost:<port>/eval -H 'content-type: application/json' \
7	//         --data "$(jq -Rn --rawfile c bench/fixtures/agenda-ladder.js '{code:$c}')" | jq .result
8	//
9	// Every input a rung's fire()/clear() reads MUST come through sense(), or these cases cannot
10	// mean anything. That is not hypothetical: TOOL's predicates once counted pickaxes straight
11	// out of bot.inventory, so eight of these cases returned TOOL no matter what world they were
12	// handed — the dry run was reading the live bot. If you add a rung, add its inputs to
13	// sense() and a case here.
14	const A = globalThis.__agenda;
15	const savedProject = A.project, savedOwner = A.owner, savedBlocked = A.blocked;
16	const savedSD = A.standDown, savedShort = A._restockShort, savedAt = A._restockShortAt;
17	const savedRemedy = A.remedy;
18	const savedSDCount = A.standDownCount, savedUnproductive = A.unproductive;
19	const savedLastProductiveAt = A.direction.lastProductiveAt;
20	const savedSpawnCamp = bot._spawnCamp;   // TODO 5g: lives on `bot`, not `A` — see agenda.js's own comment
21	const out = { version: A.version, cases: [] };
22	
23	// a "healthy at work" baseline; each case overrides only what it is testing
24	const base = {
25	  alive: true, hp: 20, food: 20, foodCount: 8, torches: 20, filler: 20, freeSlots: 20,
26	  dangerState: 'calm', survivalActive: false, light: 15, surfaceExposed: true, dHome: 30,
27	  // a weapon is part of every excursion tier, so a "healthy at work" bot carries one —
